package com.saasplatform.admin.actuator;

import com.saasplatform.admin.model.TenantSecrets;
import com.saasplatform.admin.service.TenantVaultService;
import org.springframework.boot.actuate.endpoint.annotation.ReadOperation;
import org.springframework.boot.actuate.endpoint.annotation.Selector;
import org.springframework.boot.actuate.endpoint.web.annotation.WebEndpoint;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;

@Component
@WebEndpoint(id = "tenant-credentials")
public class TenantCredentialsActuatorEndpoint {

    private final TenantVaultService vaultService;

    public TenantCredentialsActuatorEndpoint(TenantVaultService vaultService) {
        this.vaultService = vaultService;
    }

    @ReadOperation
    public TenantSecrets getTenantSecrets(@Selector String tenantSlug) {
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        boolean isSuperAdmin = authentication != null && authentication.getAuthorities().stream()
                .anyMatch(a -> a.getAuthority().equals("ROLE_SYSTEM_SUPERADMIN"));
        if (!isSuperAdmin) {
            throw new AccessDeniedException("Access to raw tenant secrets requires ROLE_SYSTEM_SUPERADMIN");
        }
        return vaultService.loadDecryptedSecrets(tenantSlug);
    }
}
